   215|export async function startAutonomous247(): Promise<void> {
   216|  if (!isAutonomous247Enabled()) {
   217|    console.log('[Autonomous247] Disabled (set IVX_AUTONOMOUS_24_7_ENABLED=true to enable)');
   218|    return;
   219|  }
   220|
   221|  if (running) {
   222|    console.log('[Autonomous247] Already running');
   223|    return;
   224|  }
   225|
   226|  startTime = new Date();
   227|  running = true;
   228|  lastHeartbeat = new Date().toISOString();
   229|  console.log('[Autonomous247] Started — polling every 60s for tasks');
   230|
   231|  const poll = async () => {
   232|    if (!running) return;
   233|
   234|    lastHeartbeat = new Date().toISOString();
   235|
