   319|/**
   320| * Advance a task to the next stage in the 16-step execution loop.
   321| */
   322|export function advanceStage(task: TaskRecord): TaskRecord {
   323|  const currentIdx = TASK_STAGES.indexOf(task.stage);
   324|  if (currentIdx < 0 || currentIdx >= TASK_STAGES.length - 1) {
   325|    return task; // Already at last stage
   326|  }
   327|  const nextStage = TASK_STAGES[currentIdx + 1];
   328|  return { ...task, stage: nextStage, heartbeat: new Date().toISOString() };
   329|}
