   397|
   398|export type CredentialCheckResult = {
   399|  variable: string;
   400|  status: 'AVAILABLE' | 'MISSING' | 'EXPIRED' | 'INVALID' | 'HTTP_401' | 'HTTP_403';
   401|  service: string;
   402|  httpResult: string | null;
   403|  traceId: string;
   404|  ownerAction: string | null;
   405|};
   406|
   407|export function checkCredentialStatus(input: {
   408|  variable: string;
   409|  exists: boolean;
   410|  service: string;
   411|  testResult?: { httpStatus?: number; ok?: boolean } | null;
   412|}): CredentialCheckResult {
   413|  const traceId = `cred-${randomUUID()}`;
   414|  if (!input.exists) {
   415|    return {
   416|      variable: input.variable,
   417|      status: 'MISSING',
   418|      service: input.service,
   419|      httpResult: null,
   420|      traceId,
   421|      ownerAction: `Provide ${input.variable} in IVX Variables or Render environment.`,
   422|    };
   423|  }
   424|  if (input.testResult?.httpStatus === 401) {
   425|    return {
   426|      variable: input.variable,
   427|      status: 'HTTP_401',
   428|      service: input.service,
   429|      httpResult: 'HTTP 401 Unauthorized',
   430|      traceId,
   431|      ownerAction: `Credential ${input.variable} is invalid or revoked. Rotate and update.`,
   432|    };
   433|  }
   434|  if (input.testResult?.httpStatus === 403) {
   435|    return {
   436|      variable: input.variable,
   437|      status: 'HTTP_403',
   438|      service: input.service,
   439|      httpResult: 'HTTP 403 Forbidden',
   440|      traceId,
   441|      ownerAction: `Credential ${input.variable} lacks required scopes. Update permissions.`,
   442|    };
   443|  }
   444|  return {
   445|    variable: input.variable,
   446|    status: 'AVAILABLE',
   447|    service: input.service,
   448|    httpResult: input.testResult?.ok ? 'OK' : null,
   449|    traceId,
   450|    ownerAction: null,
   451|  };
