   490|// ─── Task Store ────────────────────────────────────────────────────
   491|
   492|const STORE_DIR = auditDir('autonomous-ops');
   493|const TASKS_FILE = path.join(STORE_DIR, 'tasks.json');
   494|const TASKS_LOG = path.join(STORE_DIR, 'tasks.jsonl');
   495|
   496|let taskCache: TaskRecord[] | null = null;
   497|
   498|async function loadTasks(): Promise<TaskRecord[]> {
   499|  if (taskCache) return taskCache;
   500|  if (isDurableStoreConfigured()) {
   501|    try {
   502|      taskCache = await readDurableJson<TaskRecord[]>(TASKS_FILE, []);
   503|      return taskCache;
   504|    } catch (error) {
   505|      console.error('[AutonomousOps] Durable store read failed, falling back to local file:', error);
   506|    }
   507|  }
   508|  try {
   509|    taskCache = JSON.parse(await readFile(TASKS_FILE, 'utf8')) as TaskRecord[];
   510|    return taskCache;
   511|  } catch {
   512|    taskCache = [];
   513|    return taskCache;
   514|  }
   515|}
   516|
   517|async function saveTasks(tasks: TaskRecord[]): Promise<void> {
   518|  taskCache = tasks;
   519|  if (isDurableStoreConfigured()) {
   520|    await writeDurableJson(TASKS_FILE, tasks);
   521|    return;
   522|  }
   523|  await mkdir(STORE_DIR, { recursive: true });
   524|  await writeFile(TASKS_FILE, JSON.stringify(tasks, null, 2), 'utf8');
   525|}
   526|
   527|async function logTaskEvent(event: Record<string, unknown>): Promise<void> {
   528|  try {
   529|    if (isDurableStoreConfigured()) {
   530|      await appendDurableEvent(TASKS_LOG, event);
   531|      return;
   532|    }
   533|    await mkdir(STORE_DIR, { recursive: true });
   534|    await appendFile(TASKS_LOG, `${JSON.stringify(event)}\n`, 'utf8');
   535|  } catch {
   536|    // Best-effort
   537|  }
   538|}
   539|
   540|export async function enqueueTask(task: TaskRecord): Promise<TaskRecord> {
   541|  const tasks = await loadTasks();
   542|  tasks.push(task);
   543|  await saveTasks(tasks);
   544|  await logTaskEvent({ action: 'task_enqueued', taskId: task.taskId, priority: task.priority, timestamp: task.createdAt });
   545|  return task;
   546|}
   547|
   548|export async function getTask(taskId: string): Promise<TaskRecord | null> {
   549|  const tasks = await loadTasks();
   550|  return tasks.find(t => t.taskId === taskId) ?? null;
   551|}
   552|
   553|export async function updateTask(taskId: string, updater: (task: TaskRecord) => TaskRecord): Promise<TaskRecord> {
   554|  const tasks = await loadTasks();
   555|  const idx = tasks.findIndex(t => t.taskId === taskId);
   556|  if (idx < 0) throw new Error(`Task not found: ${taskId}`);
   557|  const updated = updater(tasks[idx]);
   558|  tasks[idx] = updated;
   559|  await saveTasks(tasks);
   560|  await logTaskEvent({ action: 'task_updated', taskId, status: updated.status, stage: updated.stage, timestamp: new Date().toISOString() });
   561|  return updated;
   562|}
   563|
   564|export async function cancelTask(taskId: string): Promise<TaskRecord> {
   565|  return updateTask(taskId, (t) => ({
   566|    ...t,
   567|    status: 'CANCELLED',
   568|    finishedAt: new Date().toISOString(),
   569|    heartbeat: new Date().toISOString(),
   570|  }));
   571|}
   572|
   573|export async function listTasks(filter?: {
   574|  status?: TaskStatus;
   575|  priority?: Priority;
   576|  limit?: number;
   577|}): Promise<TaskRecord[]> {
   578|  const tasks = await loadTasks();
   579|  let filtered = tasks;
   580|  if (filter?.status) filtered = filtered.filter(t => t.status === filter.status);
   581|  if (filter?.priority) filtered = filtered.filter(t => t.priority === filter.priority);
   582|  // Sort by priority then created date
   583|  filtered.sort((a, b) => {
   584|    const pa = PRIORITY_ORDER.indexOf(a.priority);
   585|    const pb = PRIORITY_ORDER.indexOf(b.priority);
   586|    if (pa !== pb) return pa - pb;
   587|    return a.createdAt.localeCompare(b.createdAt);
   588|  });
   589|  if (filter?.limit) return filtered.slice(0, filter.limit);
   590|  return filtered;
   591|}
